head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDisplayFormatter]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 데이터 표시를 처리하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "특정 Cell 의 inputType 속성이 'text', 'textarea', 'textImage', 'secret' 값이어야 동작합니다.",
        "setCellInputTypeCustom=false 일때 Column 의 typeGetter 속성이 설정되었거나 setCellInputTypeCustom=true 일때 동작합니다.",
        "사용자 함수를 설정하면 displayFormat 속성은 무시됩니다.",
        "rowIndex(필수) 파라미터로 데이터가 표시되는 형식을 설정하려는 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터로 데이터가 표시되는 형식을 설정하려는 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "formatter(필수) 파라미터로 표시되는 Cell 데이터를 변환할 사용자 정의 함수의 이름을 설정할 수 있어야 합니다.",
        "formatter(필수) 파라미터의 사용자 정의 함수의 파라미터로 Cell 의 실제 데이터가 전달됩니다.",
        "formatter(필수) 파라미터의 사용자 정의 함수의 반환값이 Cell 에 표시되는 데이터로 적용됩니다.",
        "setColumnDisplayFormatter() 메소드는 Column 단위로 적용되고, setCellDisplayFormatter() 메소드는 'custom' Column 의 특정 Cell 에만 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// formatter 후보 : 사용자 정의 함수 — Cell 의 실제(원본) 데이터를 인자로 받아 가공한 값을 반환하면 그 반환값이 화면 표시값으로 적용됨
scwin.fmt_won = function (data) {
    return data + " 원";
};
scwin.fmt_bracket = function (data) {
    return "[" + data + "]";
};
scwin.fmt_upper = function (data) {
    return String(data).toUpperCase();
};
scwin.fmt_mask = function (data) {
    return "****";
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 4개 Body 컬럼 모두 inputType=custom + typeGetter(con_inputType 값), col1(인덱스 1) 은 숨김.\n[절차] (필요시) con_inputType 선택 -> Target 재생성 -> rowIndex / columnInfo / formatter 선택 -> setCellDisplayFormatter 실행.\n[확인] 리턴창에 Cell inputType / 변경 전·후 표시값 / 동작 여부 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (formatter 가 가공할 원본 데이터)
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성하므로 5컬럼 이상은 데이터가 유실됨([createDynamicDataList 4col limit]).
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "apple", "col2": "1000", "col3": "banana", "col4": "2000" },
        { "col1": "cherry", "col2": "3500", "col3": "melon", "col4": "4200" },
        { "col1": "grape", "col2": "880", "col3": "peach", "col4": "1750" },
        { "col1": "lemon", "col2": "640", "col3": "mango", "col4": "5300" }
    ]);

    // target 생성
    //  4개 Body 컬럼 모두 inputType=custom + typeGetter 로 Cell inputType=con_inputType(기본 text) 구성.
    //   col0(idx0) / col1(idx1, ★ setColumnVisible(1,false) 로 숨김 -> 인덱스는 1 유지) / col2(idx2) / col3(idx3)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="hcol1" value="col0 (custom)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol2" value="col1 (숨김)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol3" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col3 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ 두번째 Column(인덱스 1) 을 숨김 -> "숨겨진 Column 도 포함하여 인덱스가 설정" 검증용
    scwin.target1.setColumnVisible(1, false);
}



// 모든 custom 컬럼의 Cell inputType 을 con_inputType 선택값으로 구성한다.
//  @validation1 검증용 : allow-list(text/textarea/input/textImage/secret) 이면 setCellDisplayFormatter 동작,
//                        그 외(number 등) 이면 "Invalid cell input type" 로 미동작(false) 됨을 확인한다.
//  ※ con_inputType 변경 후에는 'Target 재생성' 을 클릭해야 grid 가 새 inputType 으로 다시 그려진다.
scwin.target1_textTypeGetter = function (info) {
    let it = (typeof con_inputType !== 'undefined' && con_inputType.getValue()) ? con_inputType.getValue() : 'text';
    return { id: 'cell_' + it + '_' + info.rowIndex + '_' + info.colIndex, inputType: it, options: {} };
};



// 해당 Cell 의 표시값(formatter 가 적용된 화면값)을 조회
//  getCellDisplayData(rowIndex, columnIndex) : displayFormatter 등이 적용된 표시값을 반환
scwin.getCellDisp = function (rowIndex, columnIndex) {
    try {
        return scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    } catch (e) {
        return "(표시값 조회오류)";
    }
};



// setCellDisplayFormatter 실행 : 특정 셀에 사용자 정의 함수를 설정하고 변경 전/후 표시값을 리턴창에 출력
//  setCellDisplayFormatter(rowIndex, columnInfo, formatter) : 3인자, 성공 시 무반환 / 실패(전제 미충족) 시 false
scwin.btn_setCellDisplayFormatter_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let formatter = par_formatter.getValue();

    // 변경 전 표시값
    let before = scwin.getCellDisp(rowIndex, columnInfo);

    // 메소드 실행 (전제 미충족 시 false 반환)
    let ret = scwin.target1.setCellDisplayFormatter(rowIndex, columnInfo, formatter);

    // 화면 갱신 (셀 단위 재렌더)
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 변경 후 표시값
    let after = scwin.getCellDisp(rowIndex, columnInfo);

    let changed = (before !== after);
    let curInputType = (typeof con_inputType !== 'undefined' && con_inputType.getValue()) ? con_inputType.getValue() : 'text';
    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDisplayFormatter(" + rowIndex + ", " + columnInfo + ", '" + formatter + "')"
        + " | Cell inputType : " + curInputType
        + " | 변경 전 표시값 : " + before + " -> 변경 후 표시값 : " + after
        + " | 변경됨 : " + changed
        + (ret === false
            ? " (allow-list inputType 아님 -> 미동작/false)"
            : " (allow-list inputType -> 동작)"));
}



// @description 검증 : 사용자 함수(displayFormatter) 를 설정하면 displayFormat 속성은 무시됨을 확인한다.
//  1) 동일 Cell 에 setCellDisplayFormat 마스크 적용 후 표시값 -> 2) setCellDisplayFormatter 적용 후 표시값(formatter 결과로 바뀜, displayFormat 무시)
scwin.btn_ignoreDisplayFormat_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // '무시 확인' 은 숫자 데이터 컬럼인 col3(인덱스 3) 을 대상으로 고정 -> #,##0.00 마스크가 의미있게 적용됨
    let columnInfo = 3;

    // 1) displayFormat 마스크 먼저 적용
    scwin.target1.setCellDisplayFormat(rowIndex, columnInfo, "#,##0.00");
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}
    let afterFormat = scwin.getCellDisp(rowIndex, columnInfo);

    // 2) 동일 Cell 에 setCellDisplayFormatter 사용자 함수 적용 -> displayFormat 이 무시되고 formatter 결과로 표시됨
    scwin.target1.setCellDisplayFormatter(rowIndex, columnInfo, "scwin.fmt_won");
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}
    let afterFormatter = scwin.getCellDisp(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[col3 대상] setCellDisplayFormat('#,##0.00') 적용 표시값 : " + afterFormat
        + " -> setCellDisplayFormatter('scwin.fmt_won') 적용 후 표시값 : " + afterFormatter
        + " | displayFormat 무시됨(formatter 결과로 표시) : " + (afterFormat !== afterFormatter));
}
